operations.content:
:root {
  color-scheme: light dark;
  --bg: #f6f3ec;
  --surface: #fffdf8;
  --surface-strong: #ece6da;
  --text: #1f2925;
  --muted: #59645f;
  --line: #c9c1b3;
  --accent: #155e75;
  --accent-strong: #0e4a5d;
  --accent-soft: #d9edf2;
  --success: #17633a;
  --success-soft: #dff3e7;
  --warning: #805500;
  --warning-soft: #fff0c7;
  --danger: #8c2f39;
  --danger-soft: #f8dfe2;
  --code-bg: #17211d;
  --code-text: #f4f1e8;
  --shadow: 0 0.8rem 2.2rem rgb(31 41 37 / 10%);
  --radius: 0.75rem;
  --measure: 72rem;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #121816;
    --surface: #1a2420;
    --surface-strong: #27332e;
    --text: #f1eee5;
    --muted: #b7c0ba;
    --line: #46534d;
    --accent: #76c5d8;
    --accent-strong: #a2dcea;
    --accent-soft: #173b45;
    --success: #7bd39e;
    --success-soft: #183c27;
    --warning: #f1c56a;
    --warning-soft: #493817;
    --danger: #f1a0a9;
    --danger-soft: #4a2025;
    --code-bg: #090e0c;
    --code-text: #f5f2e9;
    --shadow: 0 0.8rem 2.2rem rgb(0 0 0 / 28%);
  }
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-size: 1.05rem;
  line-height: 1.65;
}

a {
  color: var(--accent);
  text-decoration-thickness: 0.09em;
  text-underline-offset: 0.16em;
}

a:hover {
  color: var(--accent-strong);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
summary:focus-visible {
  outline: 0.2rem solid var(--accent);
  outline-offset: 0.2rem;
}

.skip-link {
  position: absolute;
  top: 0.5rem;
  left: 0.5rem;
  z-index: 10;
  padding: 0.6rem 0.85rem;
  border-radius: 0.35rem;
  background: var(--text);
  color: var(--bg);
  transform: translateY(-150%);
}

.skip-link:focus {
  transform: translateY(0);
}

.site-header {
  border-bottom: 1px solid var(--line);
  background:
    radial-gradient(circle at 90% 0%, var(--accent-soft), transparent 35rem),
    var(--surface);
}

.site-header__inner,
.course-nav,
main,
.site-footer {
  width: min(calc(100% - 2rem), var(--measure));
  margin-inline: auto;
}

.site-header__inner {
  padding: 3.5rem 0 2.25rem;
}

.eyebrow {
  margin: 0 0 0.4rem;
  color: var(--accent);
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1,
h2,
h3 {
  line-height: 1.16;
  text-wrap: balance;
}

h1 {
  max-width: 18ch;
  margin: 0;
  font-size: clamp(2.2rem, 7vw, 4.8rem);
  letter-spacing: -0.045em;
}

h2 {
  margin-top: 3rem;
  font-size: clamp(1.55rem, 3vw, 2.25rem);
}

h3 {
  margin-top: 2rem;
  font-size: 1.25rem;
}

.lede {
  max-width: 62ch;
  margin: 1rem 0 0;
  color: var(--muted);
  font-size: 1.2rem;
}

.course-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem 1rem;
  padding-block: 0.8rem;
  font-size: 0.9rem;
}

.course-nav a[aria-current="page"] {
  color: var(--text);
  font-weight: 800;
  text-decoration: none;
}

main {
  padding-block: 2.25rem 4rem;
}

.outcome,
.callout,
.decision,
.quiz,
.reference-card {
  margin-block: 1.5rem;
  padding: 1.1rem 1.25rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.outcome {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.outcome p {
  margin: 0;
}

.label {
  display: block;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.callout {
  border-left: 0.35rem solid var(--accent);
  box-shadow: none;
}

.callout--warning {
  border-left-color: var(--warning);
  background: var(--warning-soft);
}

.callout--success {
  border-left-color: var(--success);
  background: var(--success-soft);
}

.callout > :first-child,
.decision > :first-child,
.reference-card > :first-child {
  margin-top: 0;
}

.callout > :last-child,
.decision > :last-child,
.reference-card > :last-child {
  margin-bottom: 0;
}

.badge {
  display: inline-block;
  margin: 0.15rem 0.2rem 0.15rem 0;
  padding: 0.16rem 0.48rem;
  border: 1px solid currentColor;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 800;
  line-height: 1.35;
}

.badge--safe {
  color: var(--success);
}

.badge--write {
  color: var(--warning);
}

.badge--interactive,
.badge--content {
  color: var(--danger);
}

pre {
  overflow-x: auto;
  margin-block: 1rem;
  padding: 1rem 1.15rem;
  border-radius: 0.55rem;
  background: var(--code-bg);
  color: var(--code-text);
  font: 0.92rem/1.55 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  tab-size: 2;
  white-space: pre;
}

code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

:not(pre) > code {
  padding: 0.08em 0.28em;
  border-radius: 0.25rem;
  background: var(--surface-strong);
  font-size: 0.92em;
}

.steps {
  padding-left: 1.4rem;
}

.steps > li {
  margin-block: 1.2rem;
  padding-left: 0.4rem;
}

.steps > li::marker {
  color: var(--accent);
  font-weight: 900;
}

table {
  width: 100%;
  margin-block: 1.25rem;
  border-collapse: collapse;
  background: var(--surface);
  font-size: 0.94rem;
}

th,
td {
  padding: 0.7rem;
  border: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

th {
  background: var(--surface-strong);
}

fieldset {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

legend {
  margin-bottom: 0.85rem;
  font-weight: 800;
}

.quiz label {
  display: block;
  margin-block: 0.55rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 0.4rem;
  cursor: pointer;
}

.quiz label:has(input:checked) {
  border-color: var(--accent);
  background: var(--accent-soft);
}

button {
  margin-top: 0.8rem;
  padding: 0.58rem 0.9rem;
  border: 2px solid var(--accent);
  border-radius: 0.4rem;
  background: var(--accent);
  color: var(--surface);
  font: inherit;
  font-weight: 800;
  cursor: pointer;
}

button:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.quiz__feedback {
  min-height: 1.8rem;
  margin: 0.85rem 0 0;
  font-weight: 800;
}

.quiz__feedback[data-state="correct"] {
  color: var(--success);
}

.quiz__feedback[data-state="incorrect"] {
  color: var(--danger);
}

details {
  margin-block: 0.8rem;
}

summary {
  cursor: pointer;
  font-weight: 800;
}

.lesson-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 3rem;
  padding-top: 1.2rem;
  border-top: 1px solid var(--line);
}

.site-footer {
  padding-block: 1.5rem 2.5rem;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.9rem;
}

.print-only {
  display: none;
}

@media (max-width: 44rem) {
  .site-header__inner {
    padding-top: 2.4rem;
  }

  .outcome {
    grid-template-columns: 1fr;
  }

  table {
    display: block;
    overflow-x: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  .badge,
  .callout,
  .outcome,
  .decision,
  .quiz,
  .reference-card {
    border-color: CanvasText;
  }
}

@media print {
  :root {
    color-scheme: light;
    --bg: #fff;
    --surface: #fff;
    --surface-strong: #f2f2f2;
    --text: #000;
    --muted: #333;
    --line: #777;
    --shadow: none;
  }

  body {
    font-size: 10.5pt;
  }

  .site-header__inner,
  main,
  .site-footer {
    width: 100%;
  }

  .site-header__inner {
    padding: 0 0 1rem;
  }

  .course-nav,
  .skip-link,
  .lesson-links,
  .quiz button,
  .site-footer {
    display: none;
  }

  .print-only {
    display: block;
  }

  h1 {
    font-size: 28pt;
  }

  h2 {
    break-after: avoid;
  }

  pre,
  table,
  .callout,
  .decision,
  .quiz,
  .reference-card {
    break-inside: avoid;
  }

  pre {
    border: 1px solid #555;
    background: #fff;
    color: #000;
    white-space: pre-wrap;
  }
}

document.documentElement.classList.add("js");

for (const quiz of document.querySelectorAll("[data-quiz]")) {
  const feedback = quiz.querySelector("[data-feedback]");
  const expected = quiz.dataset.answer;

  quiz.addEventListener("submit", (event) => {
    event.preventDefault();

    const selected = new FormData(quiz).get("answer");
    if (!selected) {
      feedback.textContent = "Choose one answer before checking.";
      feedback.dataset.state = "incorrect";
      return;
    }

    const correct = selected === expected;
    feedback.textContent = correct
      ? quiz.dataset.correctMessage
      : quiz.dataset.incorrectMessage;
    feedback.dataset.state = correct ? "correct" : "incorrect";
  });

  quiz.addEventListener("change", () => {
    feedback.textContent = "";
    delete feedback.dataset.state;
  });
}
